head.script:
// 테스트 설명, 유효성 값 설정
scwin.tData = {
    "description" : "[util > M > getCurrentScreen]<br/>현재 페이지에 설정된 화면 정보 중 현재 브라우저 크기에 맞는 screen 이름을 반환합니다.",
    "validation" : [
        "현재 브라우저 너비에 맞는 screen 이름을 반환해야 합니다.",
        "현재 브라우저 너비 이상인 viewport 중 가장 작은 값을 가진 screen 의 name 을 반환해야 합니다.",
        "매칭되는 screen 이 없으면 null 을 반환해야 합니다.",
    ]
}



scwin.onpageload = function () {
    // Global DataList 생성 호출
    $c.gcm.createCommonDatalist();

    // 테스트 설명, 유효성 생성
    wf_body_left.getObj("scwin").createValidation(scwin.tData);

    $c.gcm.createLabel('label="screen 설정: mobile(480), tablet(768), desktop(1280)"', '', 'label1');
};



scwin.btn_getCurrentScreen_onclick = function () {
    let mediaInfo = WebSquare.util.getMediaInfo();
    let currentScreen = mediaInfo ? mediaInfo.currentScreen : null;

    let result = [];
    result.push("현재 브라우저 너비 : " + window.innerWidth + "px");
    result.push("getCurrentScreen() : " + currentScreen);
    wf_body_bottom.getObj("scwin").setReturnValue(result.join(", "));
}
